package com.financeapp.service;

import com.financeapp.model.FinancialScheme;
import org.springframework.stereotype.Service;

import java.util.*;

/**
 * Static knowledge base of verified schemes.
 * Deterministic configuration - not generated by an LLM.
 * Returns, premiums, interest rates, or coverage amounts are not hardcoded as facts.
 * Users are explicitly instructed to check current terms on the official site.
 */
@Service
public class SchemeKnowledgeBase {

    private static final Map<String, FinancialScheme> SCHEMES = new LinkedHashMap<>();

    static {
        register(new FinancialScheme(
                "pmjjby",
                "PMJJBY (Pradhan Mantri Jeevan Jyoti Bima Yojana)",
                "GOVERNMENT",
                "Insurance",
                "Life insurance coverage for death due to any reason.",
                "Eligibility: verify on the official site",
                "https://financialservices.gov.in/pmjjby",
                "2026-10-04"
        ));

        register(new FinancialScheme(
                "pmsby",
                "PMSBY (Pradhan Mantri Suraksha Bima Yojana)",
                "GOVERNMENT",
                "Insurance",
                "Accidental death and disability insurance coverage.",
                "Eligibility: verify on the official site",
                "https://financialservices.gov.in/pmsby",
                "2026-10-04"
        ));

        register(new FinancialScheme(
                "pmjay",
                "Ayushman Bharat PM-JAY",
                "GOVERNMENT",
                "Health",
                "Health insurance cover for secondary and tertiary care hospitalization.",
                "Eligibility: verify on the official site",
                "https://nha.gov.in/PM-JAY",
                "2026-10-04"
        ));

        register(new FinancialScheme(
                "apy",
                "Atal Pension Yojana (APY)",
                "GOVERNMENT",
                "Pension",
                "Guaranteed monthly pension post-retirement for unorganized sector workers.",
                "Eligibility: verify on the official site",
                "https://jansuraksha.gov.in",
                "2026-10-04"
        ));

        register(new FinancialScheme(
                "ppf",
                "PPF (Public Provident Fund)",
                "GOVERNMENT",
                "Savings",
                "Long-term tax-advantaged government-backed savings scheme.",
                "Eligibility: verify on the official site",
                "https://www.indiapost.gov.in",
                "2026-10-04"
        ));

        register(new FinancialScheme(
                "nps",
                "NPS (National Pension System)",
                "GOVERNMENT",
                "Pension",
                "Long-term voluntary retirement savings scheme regulated by PFRDA.",
                "Eligibility: verify on the official site",
                "https://www.pfrda.org.in",
                "2026-10-04"
        ));

        register(new FinancialScheme(
                "ssy",
                "Sukanya Samriddhi Yojana (SSY)",
                "GOVERNMENT",
                "Savings",
                "Government savings scheme targeted for the education and marriage expenses of a girl child (only relevant for a girl child).",
                "Eligibility: verify on the official site",
                "https://www.indiapost.gov.in",
                "2026-10-04"
        ));

        register(new FinancialScheme(
                "scss",
                "Senior Citizens Savings Scheme (SCSS)",
                "GOVERNMENT",
                "Savings",
                "Government-backed guaranteed income savings scheme for senior citizens.",
                "Eligibility: verify on the official site",
                "https://www.indiapost.gov.in",
                "2026-10-04"
        ));

        register(new FinancialScheme(
                "bank_fd",
                "Bank Fixed Deposit (FD)",
                "BANK",
                "Savings",
                "Capital preservation with fixed returns over a chosen maturity term.",
                "Eligibility: verify on the official site",
                "https://www.rbi.org.in",
                "2026-10-04"
        ));

        register(new FinancialScheme(
                "bank_rd",
                "Bank Recurring Deposit (RD)",
                "BANK",
                "Savings",
                "Disciplined monthly recurring savings with guaranteed fixed returns.",
                "Eligibility: verify on the official site",
                "https://www.rbi.org.in",
                "2026-10-04"
        ));
    }

    private static void register(FinancialScheme scheme) {
        SCHEMES.put(scheme.id(), scheme);
    }

    public List<FinancialScheme> getAllSchemes() {
        return new ArrayList<>(SCHEMES.values());
    }

    public Optional<FinancialScheme> getSchemeById(String id) {
        if (id == null) return Optional.empty();
        return Optional.ofNullable(SCHEMES.get(id.toLowerCase()));
    }

    public List<FinancialScheme> getSchemesByCategory(String category) {
        if (category == null) return Collections.emptyList();
        List<FinancialScheme> result = new ArrayList<>();
        for (FinancialScheme s : SCHEMES.values()) {
            if (category.equalsIgnoreCase(s.category())) {
                result.add(s);
            }
        }
        return result;
    }

    public FinancialScheme getPMJJBY() { return SCHEMES.get("pmjjby"); }
    public FinancialScheme getPMSBY() { return SCHEMES.get("pmsby"); }
    public FinancialScheme getPMJAY() { return SCHEMES.get("pmjay"); }
    public FinancialScheme getAPY() { return SCHEMES.get("apy"); }
    public FinancialScheme getPPF() { return SCHEMES.get("ppf"); }
    public FinancialScheme getNPS() { return SCHEMES.get("nps"); }
    public FinancialScheme getSSY() { return SCHEMES.get("ssy"); }
    public FinancialScheme getSCSS() { return SCHEMES.get("scss"); }
    public FinancialScheme getBankFD() { return SCHEMES.get("bank_fd"); }
    public FinancialScheme getBankRD() { return SCHEMES.get("bank_rd"); }
}
